import{_ as t,a as s,o as a,a6 as r}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse('{"title":"Newsletter","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/shop/newsletter/index.md","filePath":"api/rest-api/shop/newsletter/index.md","lastUpdated":1787290888000}'),o={name:"api/rest-api/shop/newsletter/index.md"};function i(n,e,h,d,l,c){return a(),s("div",null,e[0]||(e[0]=[r('<h1 id="newsletter" tabindex="-1">Newsletter <a class="header-anchor" href="#newsletter" aria-label="Permalink to &quot;Newsletter&quot;">​</a></h1><p>The Newsletter menu lets a shopper opt in to the store&#39;s marketing emails. It is a single endpoint, and it is <strong>public</strong> — a footer signup form works for visitors who are not logged in.</p><h2 id="who-can-subscribe" tabindex="-1">Who Can Subscribe <a class="header-anchor" href="#who-can-subscribe" aria-label="Permalink to &quot;Who Can Subscribe&quot;">​</a></h2><p>A customer Bearer token is optional. Sent, the subscription row is linked to that customer&#39;s account and shows against them in the admin panel; omitted, it is stored as a guest subscription against the email address alone. Either way the storefront key is required.</p><h2 id="one-address-one-subscription" tabindex="-1">One Address, One Subscription <a class="header-anchor" href="#one-address-one-subscription" aria-label="Permalink to &quot;One Address, One Subscription&quot;">​</a></h2><p>The email must be unique across the whole subscribers list — not per channel. An address already subscribed is rejected with <code>400</code> and the message <code>The customer email has already been taken.</code>, which in practice means &quot;already subscribed&quot; rather than a fault. There is no re-subscribe call and no unsubscribe endpoint on the storefront API; a shopper who opts out does so through the link in the emails themselves.</p><h2 id="what-success-means" tabindex="-1">What Success Means <a class="header-anchor" href="#what-success-means" aria-label="Permalink to &quot;What Success Means&quot;">​</a></h2><p>A <code>201</code> means the subscription row was created. The store still sends its own confirmation email, so treat the response as &quot;request accepted&quot; rather than proof the shopper has confirmed.</p><h2 id="guard-the-form-yourself" tabindex="-1">Guard the Form Yourself <a class="header-anchor" href="#guard-the-form-yourself" aria-label="Permalink to &quot;Guard the Form Yourself&quot;">​</a></h2><p>Because the endpoint takes only the storefront key, an unprotected public form invites automated signups. Rate limiting or a captcha in front of it is the client&#39;s responsibility — the API applies no additional check beyond the email-uniqueness rule.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Method &amp; Path</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/rest-api/shop/newsletter/subscribe.html">Subscribe to Newsletter</a></td><td><code>POST /api/shop/newsletters</code></td><td>Subscribe the customer to the newsletter.</td></tr></tbody></table><p>The Newsletter endpoint is public — it needs the storefront key only. A customer Bearer token is optional and simply links the subscription to that account. See <a href="/api/rest-api/authentication.html">Authentication</a>.</p>',13)]))}const m=t(o,[["render",i]]);export{p as __pageData,m as default};
